#!/bin/bash
# ==============================================================================
# AnalogAir - Smart Vinyl Audio Streamer & AirPlay Display
# Automated Setup & Dependency Installer for Raspberry Pi
# ==============================================================================
set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# ANSI Color Codes
GREEN='\033[0;32m'
BLUE='\033[0;34m'
YELLOW='\033[1;33m'
RED='\033[0;31m'
CYAN='\033[0;36m'
NC='\033[0m'

clear
cat << "BANNER"
    _                  _                 _     _      
   / \   _ __   __ _  | | ___   __ _    / \   (_)_ __ 
  / _ \ | '_ \ / _` | | |/ _ \ / _` |  / _ \  | | '__|
 / ___ \| | | | (_| | | | (_) | (_| | / ___ \ | | |   
/_/   \_\_| |_|\__,_| |_|\___/ \__, |/_/   \_\|_|_|   
                               |___/                  
BANNER

echo -e "${GREEN}AnalogAir Smart Vinyl Audio Streamer Setup Wizard${NC}"
echo "--------------------------------------------------------"

# 1. Root check
if [ "$EUID" -eq 0 ]; then
  echo -e "${RED}Please run this script as your regular user (e.g., analogair or pi), NOT as root or with sudo.${NC}"
  echo "The installer will prompt for sudo when required."
  exit 1
fi

CURRENT_USER="$(whoami)"
USER_HOME="$HOME"

# 2. Interactive Questions
echo ""
echo -e "${YELLOW}[1/7] Configuration Setup${NC}"
read -p "Install for user [$CURRENT_USER]: " CONF_USER
CONF_USER="${CONF_USER:-$CURRENT_USER}"

DEFAULT_MUSIC_DIR="/home/$CONF_USER/Music"
read -p "Path to OwnTone Music directory [$DEFAULT_MUSIC_DIR]: " CONF_MUSIC_DIR
CONF_MUSIC_DIR="${CONF_MUSIC_DIR:-$DEFAULT_MUSIC_DIR}"

read -p "Idle Artist Name displayed on AirPlay [Audio-Technica]: " CONF_IDLE_ARTIST
CONF_IDLE_ARTIST="${CONF_IDLE_ARTIST:-Audio-Technica}"

read -p "Idle Album Name displayed on AirPlay [AT-LP60X Turntable]: " CONF_IDLE_ALBUM
CONF_IDLE_ALBUM="${CONF_IDLE_ALBUM:-AT-LP60X Turntable}"

read -p "Idle Stream Title [AnalogAir Vinyl]: " CONF_IDLE_TITLE
CONF_IDLE_TITLE="${CONF_IDLE_TITLE:-AnalogAir Vinyl}"

# 3. Audio Device Detection
echo ""
echo -e "${YELLOW}[2/7] Detecting Audio Capture Hardware${NC}"
echo "Searching for connected USB audio input devices..."
arecord -l || true
echo ""
echo "Enter your USB capture card ALSA name or leave blank for default PipeWire source (@DEFAULT_SOURCE@):"
read -p "Capture device name or card ID [@DEFAULT_SOURCE@]: " CONF_AUDIO_DEV
CONF_AUDIO_DEV="${CONF_AUDIO_DEV:-@DEFAULT_SOURCE@}"

# 4. System Packages Installation
echo ""
echo -e "${YELLOW}[3/7] Setting up OwnTone Repository & Dependencies${NC}"

sudo apt-get update
sudo apt-get install -y curl wget gnupg lsb-release sqlite3

# Add official OwnTone APT repository and keyring (supports Debian Trixie, Bookworm & Bullseye)
echo "Adding official OwnTone repository & GPG keyring..."
sudo mkdir -p /usr/share/keyrings
wget -q -O - https://raw.githubusercontent.com/owntone/owntone-apt/refs/heads/master/repo/rpi/owntone.gpg | sudo gpg --dearmor --yes -o /usr/share/keyrings/owntone-archive-keyring.gpg

DIST=$(lsb_release -cs 2>/dev/null || echo "trixie")
if [ "$DIST" != "trixie" ] && [ "$DIST" != "bookworm" ] && [ "$DIST" != "bullseye" ]; then
  DIST="trixie"
fi
sudo wget -q -O /etc/apt/sources.list.d/owntone.list "https://raw.githubusercontent.com/owntone/owntone-apt/refs/heads/master/repo/rpi/owntone-${DIST}.list"

# Refresh repos and install packages
sudo apt-get update
sudo apt-get install -y \
  owntone \
  pipewire \
  pipewire-audio-client-libraries \
  pipewire-pulse \
  wireplumber \
  alsa-utils \
  ffmpeg \
  python3 \
  python3-pip \
  python3-venv \
  python3-numpy \
  python3-pil \
  python3-gpiozero \
  python3-rpi.gpio \
  pulseaudio-utils \
  pavucontrol \
  libportaudio2 \
  portaudio19-dev \
  git \
  curl \
  avahi-daemon

# Ensure systemd journal directory exists and user has read access to journal logs
sudo mkdir -p /var/log/journal
sudo systemd-tmpfiles --create --prefix /var/log/journal 2>/dev/null || true
sudo usermod -a -G systemd-journal,audio "$CONF_USER" 2>/dev/null || true

# 5. Configure OwnTone Server (/etc/owntone.conf)
echo ""
echo -e "${YELLOW}[4/7] Configuring OwnTone Server (/etc/owntone.conf)${NC}"

PIPE_DIR="$CONF_MUSIC_DIR/AnalogAir"
mkdir -p "$PIPE_DIR"
mkdir -p "$USER_HOME/.config/analogair"
mkdir -p "$USER_HOME/.config/pipewire/filter-chain.conf.d"

# Backup original config if present
if [ -f /etc/owntone.conf ] && [ ! -f /etc/owntone.conf.original ]; then
  sudo cp /etc/owntone.conf /etc/owntone.conf.original
fi

# Ensure user and music directories have appropriate traverse permissions for OwnTone
sudo chmod 755 "$USER_HOME"
sudo chmod 755 "$CONF_MUSIC_DIR"
sudo chmod -R 777 "$PIPE_DIR"

# Write OwnTone configuration matching working vinyl pipe setup
sudo tee /etc/owntone.conf > /dev/null << CONFEOF
# OwnTone configuration generated by AnalogAir Setup Wizard
general {
	uid = "root"
	db_path = "/var/cache/owntone/songs3.db"
	logfile = "/var/log/owntone.log"
	loglevel = log
	admin_password = ""
	trusted_networks = { "localhost", "192.168", "86.0", "10.0", "fd", "lan" }
	start_buffer_ms = 1000
}

library {
	name = "AnalogAir on %h"
	port = 3689
	directories = { "$CONF_MUSIC_DIR", "$PIPE_DIR" }
	name_unknown_artist = "$CONF_IDLE_ARTIST"
	name_unknown_album = "$CONF_IDLE_ALBUM"
	artwork_basenames = { "artwork", "cover", "Folder", "AnalogAir", "AnalogAir_default" }
	artwork_individual = true
	pipe_autostart = true
}

audio {
	nickname = "AnalogAir Streamer"
}
CONFEOF

# Clean up any obsolete speaker_autoselect directive and clear any lingering drop rules
sudo sed -i '/speaker_autoselect/d' /etc/owntone.conf 2>/dev/null || true
sudo iptables -D OUTPUT -j DROP 2>/dev/null || true
sudo ip6tables -D OUTPUT -j DROP 2>/dev/null || true
sudo rm -f /tmp/analogair-pre-shutdown.pid 2>/dev/null || true

# Ensure Avahi (mDNS / Bonjour) and OwnTone services are active and running
echo "Ensuring Avahi (mDNS) and OwnTone services are running..."
sudo systemctl restart avahi-daemon 2>/dev/null || true
sudo systemctl enable avahi-daemon owntone 2>/dev/null || true
sudo systemctl restart owntone

# 6. Create Named Pipes & Virtual Audio Engine
echo ""
echo -e "${YELLOW}[5/7] Creating Named Pipes & Virtual Audio Engine${NC}"

mkfifo "$PIPE_DIR/AnalogAir" 2>/dev/null || true
mkfifo "$PIPE_DIR/AnalogAir.metadata" 2>/dev/null || true
chmod 666 "$PIPE_DIR/AnalogAir" "$PIPE_DIR/AnalogAir.metadata" 2>/dev/null || true

# Copy default standby artwork to AnalogAir_default.jpg and live AnalogAir.jpg
python3 -c "
from PIL import Image, ImageDraw
import os
path = '$PIPE_DIR/AnalogAir_default.jpg'
if not os.path.exists(path):
    img = Image.new('RGB', (1000, 1000), color='#121216')
    draw = ImageDraw.Draw(img)
    draw.ellipse([100, 100, 900, 900], outline='#2a2a32', width=8)
    draw.ellipse([250, 250, 750, 750], outline='#222228', width=6)
    draw.ellipse([400, 400, 600, 600], fill='#d97706')
    draw.ellipse([480, 480, 520, 520], fill='#121216')
    img.save(path, 'JPEG', quality=90)
" 2>/dev/null || true
cp -f "$PIPE_DIR/AnalogAir_default.jpg" "$PIPE_DIR/AnalogAir.jpg" 2>/dev/null || true

# Initialize AnalogAir SQLite settings
python3 -c "
import sqlite3
conn = sqlite3.connect('$USER_HOME/.config/analogair/settings.db')
c = conn.cursor()
c.execute('CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)')
c.execute('CREATE TABLE IF NOT EXISTS favorite_speakers (speaker_id TEXT PRIMARY KEY)')
c.execute('CREATE TABLE IF NOT EXISTS auto_connect_speakers (speaker_id TEXT PRIMARY KEY)')
c.execute('DROP TABLE IF EXISTS last_active_speakers')
c.execute('CREATE TABLE IF NOT EXISTS overrides (key TEXT PRIMARY KEY, artist TEXT, album TEXT, title TEXT, art_url TEXT)')
settings = {
    'audio_device': '$CONF_AUDIO_DEV',
    'pipe_dir': '$PIPE_DIR',
    'music_dir': '$CONF_MUSIC_DIR',
    'idle_artist': '$CONF_IDLE_ARTIST',
    'idle_album': '$CONF_IDLE_ALBUM',
    'idle_title': '$CONF_IDLE_TITLE',
    'silence_gap': '15',
    'silence_threshold': '0.0035',
    'source_type': 'vinyl',
    'enable_recognition': 'false',
    'continuous_id': 'false',
    'input_gain_db': '0.0',
    'bass_gain_db': '1.5',
    'mid_gain_db': '0.0',
    'treble_gain_db': '0.5'
}
for k, v in settings.items():
    c.execute('INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)', (k, v))
conn.commit()
conn.close()
"

# Remove any legacy pipewire tone configuration to prevent filter-chain errors
rm -f "$USER_HOME/.config/pipewire/filter-chain.conf.d/analogair-tone.conf" 2>/dev/null || true

# 7. Install Python VirtualEnv, Scripts & Web UI
echo ""
echo -e "${YELLOW}[6/7] Setting up Metadata Daemon & Web UI${NC}"
VENV_PATH="$USER_HOME/.config/analogair/venv"
python3 -m venv "$VENV_PATH" --system-site-packages
"$VENV_PATH/bin/pip" install --upgrade pip
# For Python 3.13+, PEP 594 removed audioop from the standard library.
# audioop-lts provides the official long-term support build on PyPI for Python 3.13+.
"$VENV_PATH/bin/pip" install audioop-lts shazamio sounddevice numpy requests pillow aiohttp

# Copy or write AnalogAir Daemon script
if [ -f "$SCRIPT_DIR/scripts/analogair_daemon.py" ]; then
    echo "Installing analogair_daemon.py from local repository..."
    cp -f "$SCRIPT_DIR/scripts/analogair_daemon.py" "$USER_HOME/.config/analogair/analogair_daemon.py"
else
    echo "Writing embedded analogair_daemon.py..."
    cat << 'PYEOF_DAEMON' > "$USER_HOME/.config/analogair/analogair_daemon.py"
#!/usr/bin/env python3
"""
AnalogAir Metadata & Cover Art Daemon
Handles Shazam audio recognition, MusicBrainz release group lookup,
SQLite override cache, and real-time AirPlay XML pipe updates.
"""
import asyncio
import base64
import json
import os
import re
import shutil
import sqlite3
import subprocess
import sys

# Python 3.13 audioop compatibility shim (PEP 594 removed audioop from stdlib)
try:
    import audioop
except ModuleNotFoundError:
    try:
        import audioop_lts as audioop
        sys.modules['audioop'] = audioop
    except ImportError:
        try:
            import pyaudioop as audioop
            sys.modules['audioop'] = audioop
        except ImportError:
            pass

import wave
import numpy as np
import requests
try:
    import sounddevice as sd
except Exception:
    sd = None
from shazamio import Shazam
import time
import signal
import io
from PIL import Image

HOME = os.path.expanduser("~")
DB_PATH = os.path.expanduser("~/.config/analogair/settings.db")
STATE_FILE = "/tmp/analogair_state.json"
PIPE_DIR = os.path.join(HOME, "Music/AnalogAir")
os.makedirs(PIPE_DIR, exist_ok=True)
DEFAULT_ART_PATH = os.path.join(PIPE_DIR, "AnalogAir_default.jpg")
LIVE_ART_PATH = os.path.join(PIPE_DIR, "AnalogAir.jpg")
PIPE_PATH = os.path.join(PIPE_DIR, "AnalogAir.metadata")
CACHE_DIR = "/tmp/analogair_cache"
os.makedirs(CACHE_DIR, exist_ok=True)

DEFAULT_SILENCE_THRESHOLD = 0.0025
CHECK_INTERVAL = 4

def init_db():
    os.makedirs(os.path.dirname(DB_PATH), exist_ok=True)
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    cursor.execute("CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)")
    cursor.execute("DROP TABLE IF EXISTS last_active_speakers")
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS release_overrides (
            track_key TEXT PRIMARY KEY,
            custom_artist TEXT,
            custom_album TEXT NOT NULL,
            custom_art_url TEXT,
            release_mbid TEXT,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    """)
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS sessions (
            id TEXT PRIMARY KEY,
            artist TEXT NOT NULL,
            album TEXT NOT NULL,
            first_track TEXT NOT NULL,
            art_url TEXT,
            played_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            play_count INTEGER DEFAULT 1,
            mbid TEXT,
            has_override INTEGER DEFAULT 0
        )
    """)
    conn.commit()
    conn.close()

def get_setting(key, default=""):
    try:
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute("SELECT value FROM settings WHERE key=?", (key,))
        row = c.fetchone()
        conn.close()
        return row[0] if row else default
    except:
        return default

def get_override(track_key, artist=None, title=None):
    try:
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        # 1. Exact match
        c.execute("SELECT custom_artist, custom_album, custom_art_url, release_mbid FROM release_overrides WHERE track_key=?", (track_key,))
        row = c.fetchone()
        if row:
            conn.close()
            return row

        # 2. Case-insensitive match
        c.execute("SELECT custom_artist, custom_album, custom_art_url, release_mbid FROM release_overrides WHERE LOWER(track_key)=LOWER(?)", (track_key,))
        row = c.fetchone()
        if row:
            conn.close()
            return row

        # 3. Cleaned title match (strips (Remaster), etc.)
        if artist and title:
            clean_t = sanitize_track_title(title)
            clean_key = f"{artist} - {clean_t}"
            c.execute("SELECT custom_artist, custom_album, custom_art_url, release_mbid FROM release_overrides WHERE LOWER(track_key)=LOWER(?)", (clean_key,))
            row = c.fetchone()
            if row:
                conn.close()
                return row

            # 4. Opener / title substring match for the same artist
            c.execute("SELECT custom_artist, custom_album, custom_art_url, release_mbid, track_key FROM release_overrides WHERE LOWER(custom_artist)=LOWER(?)", (artist,))
            for r in c.fetchall():
                saved_key = (r[4] or "").lower()
                clean_lower = clean_t.lower()
                if clean_lower in saved_key or saved_key.endswith(f"- {clean_lower}"):
                    conn.close()
                    return r[:4]

        conn.close()
        return None
    except:
        return None

def sanitize_album_title(title: str) -> str:
    if not title:
        return ""
    cleaned = title
    patterns = [
        # Parenthetical or bracketed notes containing remaster, edition, mix, anniversary, or mastering credits
        r"\s*[\(\[][^()\[\]]*(?:re-?master|remix|edition|version|soundtrack|anniversary|deluxe|expanded|legacy|bonus\s+track|mastered\s+by|master\s+by|half-speed)[^()\[\]]*(?:[\)\]]|$)",
        # Hyphenated suffixes
        r"\s*-\s*.*?(?:re-?master|mastered\s+by|deluxe|anniversary).*$",
        r"\s*-\s*(?:single|ep)\s*$",
        r"\s*[\(\[]\s*(?:single|ep)\s*[\)\]]$",
    ]
    for pat in patterns:
        cleaned = re.sub(pat, "", cleaned, flags=re.IGNORECASE)
    cleaned = cleaned.strip(" -–—()[]").strip()
    return cleaned if cleaned else title

def sanitize_track_title(title: str) -> str:
    if not title:
        return ""
    cleaned = title
    patterns = [
        r"\s*[\(\[][^()\[\]]*(?:re-?master|remix|edition|version|soundtrack|anniversary|deluxe|expanded|legacy|bonus\s+track|mastered\s+by|master\s+by|half-speed)[^()\[\]]*(?:[\)\]]|$)",
        r"\s*-\s*.*?(?:re-?master|mastered\s+by|deluxe|anniversary).*$",
    ]
    for pat in patterns:
        cleaned = re.sub(pat, "", cleaned, flags=re.IGNORECASE)
    cleaned = cleaned.strip(" -–—()[]").strip()
    return cleaned if cleaned else title

def restore_default_artwork():
    if not os.path.exists(DEFAULT_ART_PATH) or os.path.getsize(DEFAULT_ART_PATH) < 500:
        try:
            img = Image.new('RGB', (1000, 1000), color='#121216')
            draw = ImageDraw.Draw(img)
            draw.ellipse([100, 100, 900, 900], outline='#2a2a32', width=8)
            draw.ellipse([250, 250, 750, 750], outline='#222228', width=6)
            draw.ellipse([400, 400, 600, 600], fill='#d97706')
            draw.ellipse([480, 480, 520, 520], fill='#121216')
            img.save(DEFAULT_ART_PATH, 'JPEG', quality=90)
        except Exception:
            pass

    if os.path.exists(DEFAULT_ART_PATH):
        try:
            shutil.copyfile(DEFAULT_ART_PATH, LIVE_ART_PATH)
        except Exception as e:
            print(f"Error restoring default art: {e}", flush=True)

def write_to_pipe(xml_data):
    if os.path.exists(PIPE_PATH):
        try:
            fd = os.open(PIPE_PATH, os.O_WRONLY | os.O_NONBLOCK)
            os.write(fd, xml_data.encode("utf-8"))
            os.close(fd)
        except OSError:
            pass

def encode_b64(text):
    return base64.b64encode(text.encode("utf-8")).decode("utf-8")

def make_xml(title, artist, album):
    return f"""<item><type>61727473</type><code>6173746e</code><data encoding="base64">{encode_b64(title)}</data></item>
<item><type>61727473</type><code>61736172</code><data encoding="base64">{encode_b64(artist)}</data></item>
<item><type>61727473</type><code>6173616c</code><data encoding="base64">{encode_b64(album)}</data></item>
"""

def update_artwork(artist, album, title=None, mbid=None, custom_art_url=None, fallback_art_url=None):
    """
    Fetches and saves high-resolution artwork to LIVE_ART_PATH.
    Uses multi-stage fallback (Custom override -> Shazam art -> iTunes Album -> iTunes Song -> MusicBrainz).
    Never throws away fallbacks if one candidate fails to download.
    """
    candidates = []
    if custom_art_url and str(custom_art_url).strip():
        candidates.append(("override", custom_art_url.strip()))

    if fallback_art_url and str(fallback_art_url).strip():
        candidates.append(("shazam", fallback_art_url.strip()))

    clean_album = sanitize_album_title(album) if album else ""
    idle_album = get_setting("idle_album", "AT-LP60X Turntable")
    has_valid_album = clean_album and clean_album.lower() not in (idle_album.lower(), "analogair vinyl", "unknown album")

    headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"}

    # 1. Search iTunes by Album if album name is known and valid
    if has_valid_album and artist:
        try:
            q = requests.utils.quote(f"{artist} {clean_album}".strip())
            url = f"https://itunes.apple.com/search?term={q}&entity=album&limit=3"
            res = requests.get(url, headers=headers, timeout=6).json()
            for r in res.get("results", []):
                art = r.get("artworkUrl100", "")
                if art:
                    candidates.append(("itunes_album", art.replace("100x100bb", "1400x1400bb")))
                    break
        except Exception as e:
            print(f"[AnalogAir] iTunes album query error: {e}", flush=True)

    # 2. Search iTunes by Song (Artist + Track Title)
    if artist and title:
        try:
            clean_track = sanitize_track_title(title)
            q = requests.utils.quote(f"{artist} {clean_track}".strip())
            url = f"https://itunes.apple.com/search?term={q}&entity=song&limit=3"
            res = requests.get(url, headers=headers, timeout=6).json()
            for r in res.get("results", []):
                art = r.get("artworkUrl100", "")
                if art:
                    candidates.append(("itunes_song", art.replace("100x100bb", "1400x1400bb")))
                    break
        except Exception as e:
            print(f"[AnalogAir] iTunes song query error: {e}", flush=True)

    # 3. Search MusicBrainz CoverArtArchive if mbid is provided
    if mbid:
        candidates.append(("coverartarchive", f"https://coverartarchive.org/release/{mbid}/front-500"))

    # Try downloading candidates in priority order until one succeeds
    for source_name, url in candidates:
        try:
            if not url or not url.startswith("http"):
                continue
            resp = requests.get(url, headers=headers, timeout=8)
            if resp.status_code == 200 and len(resp.content) > 500:
                image = Image.open(io.BytesIO(resp.content))
                if image.mode in ("RGBA", "P", "LA"):
                    image = image.convert("RGB")
                os.makedirs(os.path.dirname(LIVE_ART_PATH), exist_ok=True)
                image.save(LIVE_ART_PATH, "JPEG", quality=92)
                print(f"[AnalogAir] Successfully updated live artwork from {source_name} ({len(resp.content)} bytes)", flush=True)
                return url
        except Exception as err:
            print(f"[AnalogAir] Candidate artwork failed ({source_name}: {url[:60]}...): {err}", flush=True)

    # If all new candidate sources failed: only restore default if live art doesn't exist
    if not os.path.exists(LIVE_ART_PATH) or os.path.getsize(LIVE_ART_PATH) < 500:
        restore_default_artwork()
    return None

def is_turntable_string(s):
    if not s:
        return True
    lower = s.lower().strip()
    return any(k in lower for k in ["turntable", "analogair", "idle", "unknown", "standby", "default"])

def resolve_canonical_vinyl_album(artist, title, candidate_album=None):
    """
    Identifies the definitive canonical studio album and vinyl side opener for a track.
    Distinguishes studio records from live bootlegs, greatest hits compilations, or idle strings.
    Gives a massive score boost to Track 1 (Side A / Side B openers).
    """
    if not artist or not title:
        return candidate_album, None, None

    clean_title = sanitize_track_title(title).split(" (")[0].split(" [")[0].strip()
    headers = {"User-Agent": "Mozilla/5.0"}
    best_album = candidate_album if (candidate_album and not is_turntable_string(candidate_album)) else None
    best_art = None
    best_mbid = None
    highest_score = -999

    # 1. Query iTunes Song Database to inspect tracklists & side openers
    try:
        q = requests.utils.quote(f"{artist} {clean_title}".strip())
        url = f"https://itunes.apple.com/search?term={q}&entity=song&limit=15"
        res = requests.get(url, headers=headers, timeout=5).json()
        for item in res.get("results", []):
            coll = sanitize_album_title(item.get("collectionName", ""))
            if not coll:
                continue
            t_num = item.get("trackNumber", 99)
            art = (item.get("artworkUrl100") or "").replace("100x100bb", "1400x1400bb")
            is_live = bool(re.search(r"live|bootleg|concert", coll, re.IGNORECASE) or re.search(r"live", item.get("trackName", ""), re.IGNORECASE))
            is_comp = bool(re.search(r"greatest hits|best of|anthology|singles", coll, re.IGNORECASE))

            score = 0
            # Side opener bonus (Track 1 is Side A opener)
            if t_num == 1:
                score += 80
            elif t_num in (2, 3, 4, 5, 6):
                score += 15

            # Studio LP priority (Canonical studio releases get top priority over compilations and live albums)
            if not is_live and not is_comp:
                score += 60
            if is_live:
                score -= 50
            if is_comp:
                score -= 40
                if t_num != 1:
                    score -= 50  # Strongly penalize compilation if this track is not track 1

            # If candidate_album was provided and matches (and isn't idle/turntable)
            if candidate_album and not is_turntable_string(candidate_album):
                if coll.lower() in candidate_album.lower() or candidate_album.lower() in coll.lower():
                    score += 25

            if score > highest_score:
                highest_score = score
                best_album = coll
                best_art = art
    except Exception as e:
        print(f"[AnalogAir] iTunes vinyl album resolution error: {e}", flush=True)

    # 2. Query MusicBrainz Master Release Group if available
    try:
        mb_headers = {"User-Agent": "AnalogAir/1.2.0 ( contact@analogair.local; Distearth@gmail.com )"}
        # Find artist MBID using alias recovery
        art_q = requests.utils.quote(f'alias:"{artist}" OR artist:"{artist}"')
        a_url = f"https://musicbrainz.org/ws/2/artist?query={art_q}&fmt=json&limit=1"
        a_resp = requests.get(a_url, headers=mb_headers, timeout=4)
        if a_resp.status_code == 200:
            a_data = a_resp.json()
            artists = a_data.get("artists", [])
            if artists:
                arid = artists[0].get("id")
                target_search = best_album or candidate_album
                if target_search and not is_turntable_string(target_search):
                    rg_q = requests.utils.quote(f'arid:{arid} AND releasegroupaccent:"{target_search}" AND primarytype:album')
                    rg_url = f"https://musicbrainz.org/ws/2/release-group?query={rg_q}&fmt=json&limit=3"
                    rg_resp = requests.get(rg_url, headers=mb_headers, timeout=4)
                    if rg_resp.status_code == 200:
                        rg_data = rg_resp.json()
                        for rg in rg_data.get("release-groups", []):
                            rg_id = rg.get("id")
                            rg_title = sanitize_album_title(rg.get("title", ""))
                            p_type = rg.get("primary-type") or "Album"
                            s_types = rg.get("secondary-types") or []
                            if p_type == "Album" and not s_types:
                                best_album = rg_title
                                best_mbid = rg_id
                                caa_url = f"https://coverartarchive.org/release-group/{rg_id}/front-500"
                                if not best_art:
                                    best_art = caa_url
                                break
    except Exception:
        pass

    return best_album, best_art, best_mbid

def get_capture_target():
    """
    Finds the exact audio device target to record from.
    1. Settings DB
    2. User's systemd analogair-capture.service
    3. Auto-detected USB Audio CODEC / turntable source in PipeWire/Pulse
    """
    target = get_setting("audio_device", "").strip()
    if target and target != "@DEFAULT_SOURCE@":
        return target

    # Check systemd user capture service
    svc_path = os.path.expanduser("~/.config/systemd/user/analogair-capture.service")
    if os.path.exists(svc_path):
        try:
            with open(svc_path) as f:
                content = f.read()
                m = re.search(r"--target=([^\s]+)", content)
                if m:
                    val = m.group(1).strip()
                    if val and val != "@DEFAULT_SOURCE@":
                        return val
        except Exception:
            pass

    # Auto-detect via pactl
    if shutil.which("pactl"):
        try:
            out = subprocess.check_output(["pactl", "list", "sources", "short"], text=True, timeout=2)
            for line in out.splitlines():
                parts = line.split()
                if len(parts) >= 2:
                    name = parts[1]
                    lower = name.lower()
                    if "usb" in lower or "codec" in lower or "audio" in lower or "turntable" in lower:
                        return name
        except Exception:
            pass

    return target or ""

def check_owntone_playing():
    """Checks if OwnTone is actively playing audio to AirPlay/Chromecast outputs."""
    try:
        r = requests.get("http://127.0.0.1:3689/api/player", timeout=1)
        if r.status_code == 200:
            data = r.json()
            return data.get("state") == "play"
    except Exception:
        pass
    return False

def get_owntone_player_info():
    """Returns player state and whether any speaker outputs are selected."""
    player_state = "stop"
    has_active_speakers = False
    try:
        r_p = requests.get("http://127.0.0.1:3689/api/player", timeout=1)
        if r_p.status_code == 200:
            player_state = r_p.json().get("state", "stop")
    except Exception:
        pass

    try:
        r_o = requests.get("http://127.0.0.1:3689/api/outputs", timeout=1)
        if r_o.status_code == 200:
            outputs = r_o.json().get("outputs", [])
            has_active_speakers = any(o.get("selected", False) for o in outputs)
    except Exception:
        pass

    return player_state, has_active_speakers

LAST_SPEAKERS_FILE = "/tmp/analogair_last_speakers.json"

def get_currently_selected_speakers():
    """Returns dict of {output_id: volume} for all currently selected outputs in OwnTone."""
    selected = {}
    try:
        r = requests.get("http://127.0.0.1:3689/api/outputs", timeout=2)
        if r.status_code == 200:
            for o in r.json().get("outputs", []):
                if o.get("selected", False):
                    selected[str(o.get("id"))] = int(o.get("volume", 100))
    except Exception:
        pass
    if selected:
        save_last_active_speakers(selected)
    return selected

def save_last_active_speakers(speakers_dict):
    """
    Persists last active speaker state ONLY to ephemeral /tmp/analogair_last_speakers.json.
    Never persists to SQLite so non-auto-connect speakers never persist across system reboots.
    """
    try:
        with open(LAST_SPEAKERS_FILE, "w") as f:
            json.dump(speakers_dict, f)
    except Exception:
        pass

def get_last_active_speakers():
    """
    Loads last active speakers ONLY from ephemeral /tmp file.
    Returns empty dict if file does not exist (e.g. after fresh boot).
    """
    speakers = {}
    try:
        if os.path.exists(LAST_SPEAKERS_FILE):
            with open(LAST_SPEAKERS_FILE, "r") as f:
                data = json.load(f)
                if isinstance(data, dict):
                    return {str(k): int(v) for k, v in data.items()}
    except Exception:
        pass
    return speakers

def get_auto_connect_speaker_ids():
    """
    Retrieves speaker IDs marked specifically for auto-connect (auto_connect_speakers table).
    Favorite speakers (favorite_speakers) are strictly for UI sorting and are NOT auto-connected.
    """
    auto_ids = set()
    try:
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute("CREATE TABLE IF NOT EXISTS auto_connect_speakers (speaker_id TEXT PRIMARY KEY)")
        c.execute("SELECT speaker_id FROM auto_connect_speakers")
        for row in c.fetchall():
            auto_ids.add(str(row[0]))
        conn.close()
    except Exception:
        pass
    return auto_ids

def reconnect_auto_speakers():
    """
    Connects to speakers marked with Auto-Connect upon system boot or when
    audio begins after a long period of silence (needle drop).
    Never reconnects speakers marked only as favorites.
    """
    auto_ids = get_auto_connect_speaker_ids()
    if not auto_ids:
        return
    try:
        r_o = requests.get("http://127.0.0.1:3689/api/outputs", timeout=2)
        if r_o.status_code == 200:
            outputs = r_o.json().get("outputs", [])
            for o in outputs:
                oid = str(o.get("id"))
                if oid in auto_ids and not o.get("selected", False):
                    requests.put(f"http://127.0.0.1:3689/api/outputs/{oid}", json={"selected": True, "volume": 100}, timeout=2)
                    print(f"[AnalogAir] Auto-connected marked speaker: {o.get('name')}", flush=True)
    except Exception as e:
        print(f"[AnalogAir] Speaker auto-reconnect error: {e}", flush=True)

def restore_speakers_after_purge(target_speakers=None):
    """
    Restores the exact speaker state that was active right before the purge,
    even if the speaker is not set as an auto-connect.
    If no speakers were active before the purge, falls back to reconnecting
    designated auto-connect speakers.
    """
    targets = dict(target_speakers) if target_speakers else {}
    if not targets:
        targets = get_last_active_speakers()

    restored_any = False
    if targets:
        try:
            r_o = requests.get("http://127.0.0.1:3689/api/outputs", timeout=2)
            if r_o.status_code == 200:
                outputs = r_o.json().get("outputs", [])
                for o in outputs:
                    oid = str(o.get("id"))
                    if oid in targets:
                        vol = targets[oid]
                        requests.put(f"http://127.0.0.1:3689/api/outputs/{oid}", json={"selected": True, "volume": vol}, timeout=2)
                        print(f"[AnalogAir] Restored pre-purge selected speaker: {o.get('name')} (vol={vol})", flush=True)
                        restored_any = True
        except Exception as e:
            print(f"[AnalogAir] Error restoring pre-purge speakers: {e}", flush=True)

    if not restored_any:
        reconnect_auto_speakers()

def check_and_stop_owntone_if_no_speakers():
    """
    If OwnTone is running but disconnected from all speakers (e.g. user switched receiver
    to TV), stop playback so OwnTone does not keep buffering audio into memory.
    """
    try:
        ot_state, has_speakers = get_owntone_player_info()
        if ot_state == "play" and not has_speakers:
            print("[AnalogAir] OwnTone is playing but no speakers are connected! Stopping stream to clear buffer backlog...", flush=True)
            set_owntone_player("stop")
            return True
    except Exception:
        pass
    return False

def purge_pipeline_and_restart_owntone(target_speakers=None):
    """
    Purges stale 30s FIFO pipe backlog and clears audio queues by restarting
    the user capture service and OwnTone system service.
    Remembers and preserves active speaker selection.
    """
    if target_speakers is None:
        target_speakers = get_currently_selected_speakers()
        if not target_speakers:
            target_speakers = get_last_active_speakers()

    print(f"[AnalogAir] Purging audio buffer and restarting stream in real-time (target speakers: {list(target_speakers.keys())})...", flush=True)
    try:
        subprocess.run(["systemctl", "--user", "restart", "analogair-capture.service"], timeout=5)
    except Exception as e:
        print(f"[AnalogAir] Capture restart error: {e}", flush=True)
    try:
        subprocess.run(["sudo", "systemctl", "restart", "owntone.service"], timeout=8)
    except Exception as e:
        print(f"[AnalogAir] OwnTone restart error: {e}", flush=True)
    return target_speakers

def set_owntone_player(state="play"):
    """Starts or pauses OwnTone player."""
    try:
        requests.post(f"http://127.0.0.1:3689/api/player/{state}", timeout=2)
    except Exception:
        pass

def find_usb_alsa_device():
    """Finds USB audio capture device for ALSA fallback (e.g. plughw:1,0)."""
    try:
        res = subprocess.run(["arecord", "-l"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        for line in res.stdout.splitlines():
            if line.startswith("card "):
                m = re.search(r"card\s+(\d+):.*device\s+(\d+):", line)
                if m:
                    card_num, dev_num = m.groups()
                    return f"plughw:{card_num},{dev_num}"
    except Exception:
        pass
    return "default"

def capture_sample(out_wav="/tmp/shazam_sample.wav", duration=10):
    """
    Captures a high-fidelity audio sample (default 10s) without interfering with the live OwnTone pipe.
    PipeWire allows multiple concurrent streams from the same audio source.
    """
    try:
        if os.path.exists(out_wav):
            os.remove(out_wav)
    except Exception:
        pass

    target = get_capture_target()

    # Determine PulseAudio source (safely ignoring raw ALSA hw: syntax for pulse)
    pulse_target = "default"
    if target and not target.startswith("hw:") and not target.startswith("plughw:") and target != "@DEFAULT_SOURCE@":
        pulse_target = target
    elif shutil.which("pactl"):
        try:
            res = subprocess.run(["pactl", "list", "sources", "short"], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True, timeout=1.0)
            for line in res.stdout.splitlines():
                parts = line.split()
                if len(parts) >= 2:
                    s_name = parts[1]
                    lower = s_name.lower()
                    if not s_name.endswith(".monitor") and any(k in lower for k in ["usb", "codec", "audio", "turntable", "cx231xx"]):
                        pulse_target = s_name
                        break
        except Exception:
            pass

    # 1. ffmpeg via PulseAudio/PipeWire bridge (Non-blocking: allows concurrent playback & metering)
    if shutil.which("ffmpeg") and shutil.which("pactl"):
        try:
            cmd = [
                "ffmpeg", "-y", "-loglevel", "quiet",
                "-f", "pulse", "-i", pulse_target,
                "-t", str(duration), "-ar", "44100", "-ac", "2",
                out_wav
            ]
            subprocess.run(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=duration + 3)
            if os.path.exists(out_wav) and os.path.getsize(out_wav) > 10000:
                return out_wav
        except Exception as e:
            print(f"[AnalogAir] ffmpeg pulse capture failed: {e}", flush=True)

    # 2. parec (Native PulseAudio tool, converted to wav)
    if shutil.which("parec") and shutil.which("ffmpeg"):
        try:
            p_cmd = ["parec", "--raw", "--format=s16le", "--rate=44100", "--channels=2"]
            if pulse_target and pulse_target != "default":
                p_cmd.extend(["-d", pulse_target])
            p_proc = subprocess.Popen(p_cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
            f_cmd = ["ffmpeg", "-y", "-loglevel", "quiet", "-f", "s16le", "-ar", "44100", "-ac", "2", "-i", "-", "-t", str(duration), out_wav]
            subprocess.run(f_cmd, stdin=p_proc.stdout, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=duration + 3)
            try:
                p_proc.terminate()
                p_proc.wait(timeout=0.1)
            except Exception:
                p_proc.kill()
            if os.path.exists(out_wav) and os.path.getsize(out_wav) > 10000:
                return out_wav
        except Exception as e:
            print(f"[AnalogAir] parec capture failed: {e}", flush=True)

    # 3. sounddevice (In-process PortAudio)
    if sd:
        try:
            devices = sd.query_devices()
            input_dev = None
            for idx, dev in enumerate(devices):
                if dev.get("max_input_channels", 0) > 0:
                    name = dev.get("name", "").lower()
                    if any(k in name for k in ["cx231xx", "usb", "turntable", "codec", "audio"]):
                        input_dev = idx
                        break
            
            # Record directly from sound card
            recording = sd.rec(int(duration * 44100), samplerate=44100, channels=2, device=input_dev)
            sd.wait()
            int_data = (recording * 32767).astype(np.int16)
            with wave.open(out_wav, "wb") as wf:
                wf.setnchannels(2)
                wf.setsampwidth(2)
                wf.setframerate(44100)
                wf.writeframes(int_data.tobytes())
            if os.path.exists(out_wav) and os.path.getsize(out_wav) > 10000:
                return out_wav
        except Exception as e:
            print(f"[AnalogAir] sounddevice capture failed: {e}", flush=True)

    # 4. arecord (Direct ALSA hardware capture)
    if shutil.which("arecord"):
        try:
            alsa_dev = target if (target and (target.startswith("hw:") or target.startswith("plughw:"))) else find_usb_alsa_device()
            cmd = ["arecord", "-q", "-D", alsa_dev, "-d", str(duration), "-f", "S16_LE", "-r", "44100", "-c", "2", out_wav]
            subprocess.run(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=duration + 3)
            if os.path.exists(out_wav) and os.path.getsize(out_wav) > 10000:
                return out_wav
        except Exception as e:
            print(f"[AnalogAir] arecord capture failed: {e}", flush=True)

    # 5. ffmpeg via general bridge
    if shutil.which("ffmpeg") and not os.path.exists(out_wav):
        try:
            cmd = [
                "ffmpeg", "-y", "-loglevel", "quiet",
                "-f", "pulse", "-i", "default",
                "-t", str(duration), "-ar", "44100", "-ac", "2",
                out_wav
            ]
            subprocess.run(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=duration + 3)
            if os.path.exists(out_wav) and os.path.getsize(out_wav) > 10000:
                return out_wav
        except Exception as e:
            print(f"[AnalogAir] general ffmpeg pulse capture failed: {e}", flush=True)

    # 4. PipeWire pw-record / pw-cat
    for tool in ["pw-record", "pw-cat"]:
        tool_path = shutil.which(tool)
        if tool_path:
            try:
                cmd = [tool_path]
                if tool == "pw-cat":
                    cmd.append("--record")
                if target and target != "@DEFAULT_SOURCE@":
                    cmd.extend(["--target", target])
                cmd.extend(["--rate=44100", "--channels=2", "--format=s16", out_wav])
                proc = subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                time.sleep(duration)
                proc.terminate()
                try:
                    proc.wait(timeout=2)
                except subprocess.TimeoutExpired:
                    proc.kill()

                if os.path.exists(out_wav) and os.path.getsize(out_wav) > 10000:
                    return out_wav
            except Exception as e:
                print(f"[AnalogAir] PipeWire capture via {tool} failed: {e}", flush=True)

    return None

def compute_wav_rms(wav_path):
    if not wav_path or not os.path.exists(wav_path):
        return 0.0
    try:
        with wave.open(wav_path, "rb") as wf:
            n_frames = wf.getnframes()
            if n_frames == 0:
                return 0.0
            frames = wf.readframes(n_frames)
            data = np.frombuffer(frames, dtype=np.int16).astype(np.float32) / 32768.0
            if len(data) == 0:
                return 0.0
            return float(np.sqrt(np.mean(data**2)))
    except Exception as e:
        print(f"[AnalogAir] Error reading WAV RMS: {e}", flush=True)
        return 0.0

async def main():
    init_db()
    shazam = Shazam()
    is_playing = False
    session_locked = False
    current_track_id = None
    silence_counter = 0
    was_silent_session = True

    restore_default_artwork()
    idle_artist = get_setting("idle_artist", "Audio-Technica")
    idle_album = get_setting("idle_album", "AT-LP60X Turntable")
    idle_title = get_setting("idle_title", "AnalogAir Vinyl")

    write_to_pipe(make_xml(idle_title, idle_artist, idle_album))
    print("[AnalogAir] Daemon running with PipeWire audio monitoring.", flush=True)

    silence_start_time = time.time()

    # Initial state
    try:
        with open(STATE_FILE, "w") as sf:
            json.dump({
                "status": "idle",
                "artist": idle_artist,
                "album": idle_album,
                "title": idle_title,
                "art_url": "/api/artwork/custom-standby.jpg",
                "rms": 0.0,
                "was_silent_session": True,
                "silence_start_time": silence_start_time
            }, sf)
    except Exception:
        pass

    last_artist = idle_artist
    last_album = idle_album
    last_title = idle_title

    while True:
        # Check if user interaction in web interface triggered the resync while silent
        if os.path.exists("/tmp/analogair_web_resync"):
            try:
                os.remove("/tmp/analogair_web_resync")
            except Exception:
                pass
            print("[AnalogAir] Web interface interaction triggered resync purge while idle. Auto-connect speakers pre-armed.", flush=True)
            was_silent_session = False

        enable_recognition = get_setting("enable_recognition", "false").lower() == "true"
        continuous_mode = get_setting("continuous_id", "false").lower() == "true"
        silence_timeout_sec = int(get_setting("silence_gap", "15"))
        silence_thresh = float(get_setting("silence_threshold", str(DEFAULT_SILENCE_THRESHOLD)))
        max_silence_counts = max(1, silence_timeout_sec // CHECK_INTERVAL)

        sample_duration = int(get_setting("sample_duration", "10"))
        sample_file = capture_sample(duration=sample_duration)
        rms = compute_wav_rms(sample_file)
        has_signal = (rms >= silence_thresh)

        print(f"[AnalogAir] Audio level: RMS={rms:.5f} (Threshold={silence_thresh:.5f}) | Has Signal={has_signal} | State Playing={is_playing} | Recognition={enable_recognition}", flush=True)

        if not has_signal:
            silence_counter += 1
            # Check if OwnTone is streaming to nowhere (e.g. switched to TV)
            check_and_stop_owntone_if_no_speakers()

            if is_playing and silence_counter >= max_silence_counts:
                print(f"[AnalogAir] Silence confirmed ({silence_timeout_sec}s). Needle lifted, restoring Standby.", flush=True)
                write_to_pipe(make_xml(idle_title, idle_artist, idle_album))
                restore_default_artwork()
                is_playing = False
                session_locked = False
                current_track_id = None
                resolved_art = None
                was_silent_session = True
                silence_start_time = time.time()
                set_owntone_player("stop")
                try:
                    with open(STATE_FILE, "w") as sf:
                        json.dump({
                            "status": "idle",
                            "artist": idle_artist,
                            "album": idle_album,
                            "title": idle_title,
                            "art_url": "",
                            "rms": float(rms),
                            "matched_via": "idle_default",
                            "was_silent_session": True,
                            "silence_start_time": silence_start_time
                        }, sf)
                except Exception:
                    pass
            elif is_playing:
                # Brief pause between tracks on vinyl side, keep playing state
                current_art = resolved_art if (resolved_art and resolved_art.startswith("http")) else f"/api/artwork/current.jpg?t={int(time.time())}"
                try:
                    with open(STATE_FILE, "w") as sf:
                        json.dump({
                            "status": "playing",
                            "artist": last_artist,
                            "album": last_album,
                            "title": last_title,
                            "art_url": current_art,
                            "rms": float(rms),
                            "matched_via": "groove"
                        }, sf)
                except Exception:
                    pass
        else:
            # Signal detected (music playing)
            if not is_playing:
                is_playing = True
                print(f"[AnalogAir] Needle drop detected! (RMS: {rms:.5f} >= {silence_thresh:.5f})", flush=True)

                ot_state, has_speakers = get_owntone_player_info()
                print(f"[AnalogAir] Current OwnTone status on needle drop: state='{ot_state}', active_speakers={has_speakers}", flush=True)

                # Purge pipeline backlog and restore active speakers after extended silence or startup
                if was_silent_session:
                    print("[AnalogAir] Audio detected after extended silence. Purging 30s buffer backlog and restoring active speakers...", flush=True)
                    target_speakers = get_currently_selected_speakers()
                    if not target_speakers:
                        target_speakers = get_last_active_speakers()
                    purge_pipeline_and_restart_owntone(target_speakers)
                    time.sleep(1.8)
                    restore_speakers_after_purge(target_speakers)
                    was_silent_session = False
                
                # Start or resume OwnTone stream
                set_owntone_player("play")

            silence_counter = 0

            # Check if Recognition is Disabled (No Recognition / Resource Saver Mode)
            if not enable_recognition:
                # Music streams with default art & labels; no Shazam lookup and no session recording
                try:
                    with open(STATE_FILE, "w") as sf:
                        json.dump({
                            "status": "playing",
                            "artist": idle_artist,
                            "album": idle_album,
                            "title": idle_title,
                            "art_url": "",
                            "rms": float(rms),
                            "matched_via": "idle_default"
                        }, sf)
                except Exception:
                    pass
                await asyncio.sleep(CHECK_INTERVAL)
                continue

            if not continuous_mode and session_locked:
                # Still spinning the current identified record side
                current_art = resolved_art if (resolved_art and resolved_art.startswith("http")) else f"/api/artwork/current.jpg?t={int(time.time())}"
                try:
                    with open(STATE_FILE, "w") as sf:
                        json.dump({
                            "status": "playing",
                            "artist": last_artist,
                            "album": last_album,
                            "title": last_title,
                            "art_url": current_art,
                            "rms": float(rms),
                            "matched_via": "shazam"
                        }, sf)
                except Exception:
                    pass
                await asyncio.sleep(CHECK_INTERVAL)
                continue

            # If not identified yet, write active playing state immediately so UI drops the needle!
            if current_track_id is None:
                try:
                    with open(STATE_FILE, "w") as sf:
                        json.dump({
                            "status": "playing",
                            "artist": idle_artist,
                            "album": "Vinyl Playback",
                            "title": "Listening & Identifying...",
                            "art_url": f"/api/artwork/current.jpg?t={int(time.time())}",
                            "rms": float(rms),
                            "matched_via": "listening"
                        }, sf)
                except Exception:
                    pass

            if sample_file and os.path.exists(sample_file):
                print(f"[AnalogAir] Submitting {os.path.getsize(sample_file)} byte sample to Shazam for track identification...", flush=True)
                try:
                    out = await shazam.recognize(sample_file)
                    track = out.get("track", {})
                    if track:
                        track_id = track.get("key")
                        raw_title = track.get("title", idle_title)
                        raw_artist = track.get("subtitle", idle_artist)
                        print(f"[AnalogAir] Shazam match found: '{raw_title}' by '{raw_artist}' (ID: {track_id})", flush=True)
                        if track_id != current_track_id:
                            images = track.get("images", {})
                            shazam_art = (
                                images.get("coverarthq") or
                                images.get("coverart") or
                                track.get("share", {}).get("image") or
                                track.get("hub", {}).get("image") or
                                images.get("background")
                            )

                            raw_album = None
                            for s in track.get("sections", []):
                                for item in s.get("metadata", []):
                                    if item.get("title", "").strip().lower() == "album":
                                        raw_album = item.get("text", "").strip()
                                        break
                                if raw_album:
                                    break
                            if not raw_album:
                                raw_album = track.get("album") or idle_album
                            base_album = sanitize_album_title(raw_album)

                            track_key = f"{raw_artist} - {raw_title}"
                            override = get_override(track_key, artist=raw_artist, title=raw_title)
                            custom_art_url = None

                            if override:
                                artist = override[0] or raw_artist
                                album = sanitize_album_title(override[1])
                                custom_art_url = override[2]
                                mbid = override[3]
                                print(f"[AnalogAir] Applying saved local override: '{artist}' - '{album}'", flush=True)
                            else:
                                artist = raw_artist
                                canon_album, canon_art, canon_mbid = resolve_canonical_vinyl_album(artist, raw_title, candidate_album=base_album)
                                album = sanitize_album_title(canon_album or base_album)
                                custom_art_url = canon_art
                                mbid = canon_mbid
                                print(f"[AnalogAir] Resolved canonical vinyl album: '{artist}' - '{album}' (MBID: {mbid})", flush=True)

                            clean_title = sanitize_track_title(raw_title)
                            display_title = clean_title if continuous_mode else "AnalogAir"
                            last_artist = artist
                            last_album = album
                            last_title = display_title

                            resolved_art = update_artwork(artist, album, title=raw_title, mbid=mbid, custom_art_url=custom_art_url, fallback_art_url=shazam_art)
                            active_art_url = resolved_art if (resolved_art and resolved_art.startswith("http")) else f"/api/artwork/current.jpg?t={int(time.time())}"
                            write_to_pipe(make_xml(display_title, artist, album))
                            
                            current_track_id = track_id
                            if not continuous_mode and resolved_art:
                                session_locked = True
                                print(f"[AnalogAir] Album side locked with matched artwork: '{album}'. Artwork will remain active until needle lift.", flush=True)

                            try:
                                with open(STATE_FILE, "w") as sf:
                                    json.dump({
                                        "status": "playing",
                                        "artist": artist,
                                        "album": album,
                                        "title": display_title,
                                        "art_url": active_art_url,
                                        "rms": float(rms),
                                        "matched_via": "override" if override else "shazam"
                                    }, sf)
                            except Exception:
                                pass

                            # Log session in SQLite
                            try:
                                conn = sqlite3.connect(DB_PATH)
                                c = conn.cursor()
                                sess_id = f"{artist}_{album}"
                                c.execute("SELECT play_count FROM sessions WHERE id=?", (sess_id,))
                                srow = c.fetchone()
                                if srow:
                                    c.execute("UPDATE sessions SET play_count=play_count+1, played_at=CURRENT_TIMESTAMP WHERE id=?", (sess_id,))
                                else:
                                    c.execute("""
                                        INSERT INTO sessions (id, artist, album, first_track, art_url, mbid, has_override)
                                        VALUES (?, ?, ?, ?, ?, ?, ?)
                                    """, (sess_id, artist, album, raw_title, resolved_art, mbid, 1 if override else 0))
                                conn.commit()
                                conn.close()
                            except Exception as le:
                                print(f"[AnalogAir] Session logging error: {le}", flush=True)
                    else:
                        print(f"[AnalogAir] Shazam found no match for this sample, will retry on next check.", flush=True)
                except Exception as e:
                    print(f"[AnalogAir] Shazam error: {e}", flush=True)

        await asyncio.sleep(CHECK_INTERVAL)

if __name__ == "__main__":
    asyncio.run(main())

PYEOF_DAEMON
