def get_db():
    conn = sqlite3.connect(str(DB_PATH))
    conn.row_factory = sqlite3.Row
    return conn

def sanitize_album_title(title: str) -> str:
    if not title:
        return ""
    cleaned = title
    patterns = [
        # Parenthetical or bracketed notes containing remaster, edition, mix, anniversary, or mastering credits
        r"\s*[\(\[][^()\[\]]*(?:re-?master|remix|edition|version|soundtrack|anniversary|deluxe|expanded|legacy|bonus\s+track|mastered\s+by|master\s+by|half-speed)[^()\[\]]*(?:[\)\]]|$)",
        # Hyphenated suffixes
        r"\s*-\s*.*?(?:re-?master|mastered\s+by|deluxe|anniversary).*$",
        r"\s*-\s*(?:single|ep)\s*$",
        r"\s*[\(\[]\s*(?:single|ep)\s*[\)\]]$",
    ]
    for pat in patterns:
        cleaned = re.sub(pat, "", cleaned, flags=re.IGNORECASE)
    cleaned = cleaned.strip(" -–—()[]").strip()
    return cleaned if cleaned else title

def sanitize_track_title(title: str) -> str:
    if not title:
        return ""
    cleaned = title
    patterns = [
        r"\s*[\(\[][^()\[\]]*(?:re-?master|remix|edition|version|soundtrack|anniversary|deluxe|expanded|legacy|bonus\s+track|mastered\s+by|master\s+by|half-speed)[^()\[\]]*(?:[\)\]]|$)",
        r"\s*-\s*.*?(?:re-?master|mastered\s+by|deluxe|anniversary).*$",
    ]
    for pat in patterns:
        cleaned = re.sub(pat, "", cleaned, flags=re.IGNORECASE)
    cleaned = cleaned.strip(" -–—()[]").strip()
    return cleaned if cleaned else title

IS_SHUTTING_DOWN = False

def heal_system_services():
    """Restores OwnTone and Avahi services, removes obsolete config lines, and clears network blocks."""
    try:
        conf_p = Path("/etc/owntone.conf")
        if conf_p.exists():
            content = conf_p.read_text(encoding="utf-8")
            if "speaker_autoselect" in content:
                clean_lines = [l for l in content.splitlines() if "speaker_autoselect" not in l]
                subprocess.run(
                    ["sudo", "tee", "/etc/owntone.conf"],
                    input=("\n".join(clean_lines) + "\n").encode("utf-8"),
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    timeout=2
                )
                subprocess.run(["sudo", "systemctl", "restart", "owntone"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=4)
    except Exception:
        pass

    try:
        subprocess.run(["sudo", "iptables", "-D", "OUTPUT", "-j", "DROP"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=1)
        subprocess.run(["sudo", "ip6tables", "-D", "OUTPUT", "-j", "DROP"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=1)
        p = Path("/tmp/analogair-pre-shutdown.pid")
        if p.exists():
            p.unlink()
    except Exception:
        pass

    try:
        res = subprocess.run(["systemctl", "is-active", "owntone"], stdout=subprocess.PIPE, text=True, timeout=1)
        if res.stdout.strip() != "active":
            subprocess.run(["sudo", "systemctl", "start", "avahi-daemon"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=2)
            subprocess.run(["sudo", "systemctl", "restart", "owntone"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=4)
    except Exception:
        pass

def init_db():
    heal_system_services()
    CONFIG_DIR.mkdir(parents=True, exist_ok=True)
    with get_db() as conn:
        c = conn.cursor()
        c.execute("CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)")
        c.execute("DROP TABLE IF EXISTS last_active_speakers")
        c.execute("""
            CREATE TABLE IF NOT EXISTS release_overrides (
                track_key TEXT PRIMARY KEY,
                custom_artist TEXT,
                custom_album TEXT NOT NULL,
                custom_art_url TEXT,
                release_mbid TEXT,
                format TEXT,
                year TEXT,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        try:
            c.execute("ALTER TABLE release_overrides ADD COLUMN format TEXT")
        except Exception:
            pass
        try:
            c.execute("ALTER TABLE release_overrides ADD COLUMN year TEXT")
        except Exception:
            pass
        c.execute("""
            CREATE TABLE IF NOT EXISTS sessions (
                id TEXT PRIMARY KEY,
                artist TEXT,
                album TEXT,
                first_track TEXT,
                art_url TEXT,
                played_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
