# --- 7b. System Power Management ---
async def _execute_clean_power(action: str):
    global IS_SHUTTING_DOWN
    IS_SHUTTING_DOWN = True

    # 1. Clear ephemeral speaker states so next boot starts with a clean slate
    if LAST_SPEAKERS_FILE.exists():
        try:
            LAST_SPEAKERS_FILE.unlink()
        except Exception:
            pass

    # 2. Cleanly stop OwnTone player and DESELECT ALL OUTPUTS in OwnTone's DB
    try:
        async with aiohttp.ClientSession() as session:
            await session.put(f"{OWNTONE_BASE}/api/player/stop", timeout=1.5)
            async with session.get(f"{OWNTONE_BASE}/api/outputs", timeout=2) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    for o in data.get("outputs", []):
                        if o.get("selected", False):
                            oid = str(o.get("id"))
                            await session.put(f"{OWNTONE_BASE}/api/outputs/{oid}", json={"selected": False}, timeout=1.5)
    except Exception as e:
        print(f"[AnalogAir Web] Pre-shutdown output deselect error: {e}", flush=True)

    await asyncio.sleep(0.3)

    try:
        # 3. Run dedicated pre-shutdown network killer script FIRST
        # This cuts network interfaces, drops outbound traffic, and kills daemon loops
        # BEFORE OwnTone can send AirPlay packets or wake up receivers.
        pre_shutdown_script = Path("/usr/local/bin/analogair-pre-shutdown.sh")
        if pre_shutdown_script.exists():
            subprocess.run(["sudo", str(pre_shutdown_script)], timeout=5)
        else:
            # Inline fallback: DROP network traffic FIRST, take down interfaces, then kill processes
            subprocess.run([
                "sudo", "sh", "-c",
                "iptables -I OUTPUT 1 -o lo -j ACCEPT 2>/dev/null; iptables -I OUTPUT 2 -j DROP 2>/dev/null; ip6tables -I OUTPUT 1 -o lo -j ACCEPT 2>/dev/null; ip6tables -I OUTPUT 2 -j DROP 2>/dev/null"
            ], timeout=2)
            subprocess.run([
                "sudo", "sh", "-c",
                "for dev in /sys/class/net/*; do d=$(basename $dev); [ \"$d\" != \"lo\" ] && ip link set $d down 2>/dev/null; done"
            ], timeout=2)
            subprocess.run(["sudo", "pkill", "-9", "-f", "analogair_daemon.py"], timeout=2)
            subprocess.run(["sudo", "pkill", "-9", "-f", "analogair_capture.py"], timeout=2)
            subprocess.run(["sudo", "pkill", "-9", "owntone"], timeout=2)
            subprocess.run(["sudo", "pkill", "-9", "avahi-daemon"], timeout=2)
    except Exception as e:
        print(f"[AnalogAir Web] Pre-power network kill error: {e}", flush=True)

    # 4. Trigger clean poweroff or reboot
    if action == "shutdown":
        subprocess.Popen(["sudo", "systemctl", "poweroff"])
    else:
        subprocess.Popen(["sudo", "systemctl", "reboot"])

async def handle_system_power(request):
    try:
        data = await request.json()
        action = data.get("action", "shutdown")
        if action not in ("shutdown", "reboot"):
            return web.json_response({"error": "Invalid action"}, status=400)

        print(f"[AnalogAir Web] Power action '{action}' requested. Killing network connections and halting cleanly...", flush=True)
        asyncio.create_task(_execute_clean_power(action))
        return web.json_response({
            "success": True,
            "message": f"System {action} initiated. Network connections killed to prevent speaker reactivation."
        })
    except Exception as e:
        return web.json_response({"error": str(e)}, status=500)

# --- 8. Artwork Serving & Upload ---
NO_CACHE_HEADERS = {
    "Cache-Control": "no-cache, no-store, must-revalidate",
    "Pragma": "no-cache",
    "Expires": "0"
}

def ensure_default_artwork():
    """Generates guaranteed 1000x1000 high-resolution vinyl standby artwork if missing."""
    if DEFAULT_ART_PATH.exists() and DEFAULT_ART_PATH.stat().st_size > 500:
        return True
    try:
        PIPE_DIR.mkdir(parents=True, exist_ok=True)
        from PIL import Image, ImageDraw
        img = Image.new('RGB', (1000, 1000), color='#121216')
        draw = ImageDraw.Draw(img)
        # Concentric vinyl record grooves
        for r in range(120, 460, 18):
            draw.ellipse([500 - r, 500 - r, 500 + r, 500 + r], outline='#1e1e26', width=2)
        # Outer boundary ring
        draw.ellipse([80, 80, 920, 920], outline='#2a2a34', width=8)
        # Gold/amber record label
        draw.ellipse([340, 340, 660, 660], fill='#d97706', outline='#b45309', width=6)
        # Inner spindle hole
        draw.ellipse([475, 475, 525, 525], fill='#0e0e12')
        img.save(str(DEFAULT_ART_PATH), 'JPEG', quality=90)
        if not LIVE_ART_PATH.exists() or LIVE_ART_PATH.stat().st_size <= 500:
            shutil.copyfile(str(DEFAULT_ART_PATH), str(LIVE_ART_PATH))
        return True
    except Exception as e:
        print(f"[AnalogAir Web] Note: Could not generate default artwork via PIL ({e})", flush=True)
        return False

async def serve_current_art(request):
    if not LIVE_ART_PATH.exists() or LIVE_ART_PATH.stat().st_size <= 500:
        ensure_default_artwork()
    if LIVE_ART_PATH.exists() and LIVE_ART_PATH.stat().st_size > 500:
        return web.FileResponse(LIVE_ART_PATH, headers=NO_CACHE_HEADERS)
    return await serve_standby_art(request)

async def serve_standby_art(request):
    if not DEFAULT_ART_PATH.exists() or DEFAULT_ART_PATH.stat().st_size <= 500:
        ensure_default_artwork()
    if DEFAULT_ART_PATH.exists() and DEFAULT_ART_PATH.stat().st_size > 500:
        return web.FileResponse(DEFAULT_ART_PATH, headers=NO_CACHE_HEADERS)
    if LIVE_ART_PATH.exists() and LIVE_ART_PATH.stat().st_size > 500:
        return web.FileResponse(LIVE_ART_PATH, headers=NO_CACHE_HEADERS)
    for fallback in [
        UI_DIR / "assets" / "default_vinyl.jpg",
        UI_DIR / "assets" / "default_idle.jpg",
        FALLBACK_ART_PATH,
        FALLBACK_SRC_ART
    ]:
        if fallback.exists() and fallback.stat().st_size > 500:
            return web.FileResponse(fallback, headers=NO_CACHE_HEADERS)
    return web.Response(status=404)

async def serve_live_pipe_art(request):
    if LIVE_ART_PATH.exists():
        return web.FileResponse(LIVE_ART_PATH, headers=NO_CACHE_HEADERS)
    return await serve_standby_art(request)

async def upload_default_art(request):
    try:
        PIPE_DIR.mkdir(parents=True, exist_ok=True)
        if request.content_type == "application/json":
            body = await request.json()
            image_b64 = body.get("imageBase64", "")
            if not image_b64:
                return web.json_response({"error": "No image data provided"}, status=400)
            if "," in image_b64:
                image_b64 = image_b64.split(",", 1)[1]
            raw_bytes = base64.b64decode(image_b64)
            with open(DEFAULT_ART_PATH, "wb") as f:
                f.write(raw_bytes)
            shutil.copyfile(DEFAULT_ART_PATH, LIVE_ART_PATH)
            return web.json_response({"success": True, "artUrl": "/api/artwork/custom-standby.jpg"})
        elif request.content_type.startswith("multipart/"):
            reader = await request.multipart()
            field = await reader.next()
            if field and field.name in ['file', 'image']:
                with open(DEFAULT_ART_PATH, 'wb') as f:
                    while True:
                        chunk = await field.read_chunk()
                        if not chunk:
                            break
                        f.write(chunk)
                shutil.copyfile(DEFAULT_ART_PATH, LIVE_ART_PATH)
                return web.json_response({"success": True, "artUrl": "/api/artwork/custom-standby.jpg"})
            return web.json_response({"error": "No file in multipart form"}, status=400)
        else:
            return web.json_response({"error": "Unsupported Content-Type"}, status=400)
    except Exception as e:
        return web.json_response({"error": str(e)}, status=500)

