[Unit]
Description=Howchoo Pi Power Button Listener
After=multi-user.target

[Service]
Type=simple
Restart=always
RestartSec=2
ExecStart=/usr/bin/python3 /usr/local/bin/listen-for-shutdown.py

[Install]
WantedBy=multi-user.target
SERVEOF

